  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
  yield_time_ms: 30000,
  max_output_tokens: 30000,
  tty: false
});
text(r.output);

const queries = [
  "FiniteInAffine descends field extension",
  "finite in affine faithfully flat descent",
  "affine open descends Galois",
  "Galois stable affine open descends",
  "base change finiteInAffine"
];
for (const q of queries) {
  const r = await tools.exec_command({
    cmd: "\"$HORIZON_BIN\" search \"" + q + "\" --json",
    workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
    yield_time_ms: 30000,
    max_output_tokens: 18000
  });
  text("QUERY: " + q + "\n" + r.output);
}

const paths=[
["AJC lakefile","sed -n '1,180p' lakefile.toml","/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge"],
["AJCR lakefile","sed -n '1,180p' lakefile.toml","/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"]
];
const rs=await Promise.all(paths.map(x=>tools.exec_command({cmd:x[1],workdir:x[2],yield_time_ms:10000,max_output_tokens:10000})));
rs.forEach((r,i)=>text(paths[i][0]+"\n"+r.output));

const reads = [
  ["AJCR QPFIA", "nl -ba AlgebraicJacobian/Descent/QuasiProjectiveFiniteInAffine.lean | sed -n '1,100p'"],
  ["AJCR projective", "nl -ba AlgebraicJacobian/Projective/ProjectiveMorphism.lean | sed -n '1,105p'"]
];
const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const rs=await Promise.all(reads.map(x=>tools.exec_command({cmd:x[1],workdir:wd,yield_time_ms:10000,max_output_tokens:18000})));
rs.forEach((r,i)=>text(reads[i][0]+"\n"+r.output));

const r = await tools.exec_command({
  cmd: "\"$HORIZON_BIN\" inbox show I-2007 --json 2>/dev/null | jq '{id,status,body,comments: [.comments[] | {author,at,body}]}'",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 30000,
  max_output_tokens: 10000
});
text(r.output);

